// P14 (docs/context/P14_SPEC.md, RELAY_PROTOCOL.md "Client rules for blobs" / "Blob garbage collection"): bill files are
// uploaded before the ops that reference them, never deleted by clients, and declared per snapshot so the relay can
// collect the rest. All data is SYNTHETIC (generated bytes, made-up bills).
import 'dart:convert';
import 'dart:io';
import 'dart:math';
import 'dart:typed_data';

import 'package:relay/relay.dart';
import 'package:test/test.dart';
import 'package:wallet_core/wallet_core.dart';

Uint8List bytesOf(int n, [int seed = 1]) {
  final r = Random(seed);
  return Uint8List.fromList(List.generate(n, (_) => r.nextInt(256)));
}

NormalizedBill nb(String ext) =>
    NormalizedBill(source: BillSource.pdf, externalId: 'jir:synthetic-$ext', date: '2026-02-25', total: 1000, payee: 'Test Shop');

/// A relay in memory whose blob PUTs can fail (all, or some hashes with a chosen failure) and whose next file PUT can
/// fail once; records the order of uploads.
class FlakyRelay extends MemoryTransport {
  FlakyRelay({super.now});
  bool failBlobs = false;
  final failHashes = <String, TransportFailure>{};
  bool failNextPut = false;
  final order = <String>[];
  @override
  Future<void> put(String device, int seq, List<int> bytes) {
    order.add('put');
    if (failNextPut) {
      failNextPut = false;
      throw const TransportException(TransportFailure.unreachable, 'down');
    }
    return super.put(device, seq, bytes);
  }

  @override
  Future<void> putBlob(String hash, List<int> bytes) {
    order.add('putBlob');
    if (failBlobs) throw const TransportException(TransportFailure.unreachable, 'down');
    if (failHashes[hash] case final f?) throw TransportException(f, 'refused');
    return super.putBlob(hash, bytes);
  }
}

void main() {
  late VaultKey key;
  late FlakyRelay relay;
  var now = DateTime.utc(2026, 11, 1);
  final repos = <WalletRepo>[];
  WalletRepo mk() => WalletRepo.inMemory()..also(repos.add);
  Future<SyncReport> run(WalletRepo r) => SyncEngine(relay, key, now: () => now).run(r);
  var bumps = 0;
  // An op, so the next snapshot check has something not covered yet.
  void bump(WalletRepo r) => r.updateSettings({'returnReminderDays': 1 + (bumps++ % 20)});

  /// Runs [r] (after the others) so a snapshot is due: more than 7 days since the newest one.
  Future<void> snapshotBy(WalletRepo r, List<WalletRepo> others) async {
    now = now.add(const Duration(days: 8));
    bump(r);
    for (final o in others) {
      await run(o);
    }
    await run(r);
  }

  setUp(() {
    key = VaultKey.generate();
    now = DateTime.utc(2026, 11, 1);
    relay = FlakyRelay(now: () => now);
  });
  tearDown(() {
    for (final r in repos) {
      r.close();
    }
    repos.clear();
  });

  group('upload before ops', () {
    test('a failed blob PUT holds that bill\'s file fields while the rest goes up; they go once the blob is stored', () async {
      final a = mk(), b = mk();
      bump(a);
      await run(a);
      final ref = await BlobStore(a, key).add(bytesOf(400, 1), 'jpg');
      final (id, _) = a.importBill(nb('wait'), file: ref);
      a.addTransaction(date: '2026-02-26', amount: -500, category: 'Groceries');
      relay.failBlobs = true;
      final r1 = await run(a);
      expect((r1.sent > 0, r1.blobsWaiting), (true, 1));
      final held = a.pendingOps();
      expect(held, hasLength(1));
      expect(held.single.$2.id, id);
      expect(held.single.$2.fields.keys.toSet().difference({'blob', 'blob_type', 'blob_bytes', 'deleted'}), isEmpty);
      expect(held.single.$2.fields['blob'], ref.hash);
      await run(b);
      expect(b.transactions(), hasLength(1), reason: 'the rest of the outbox went on');
      expect(b.bill(id), isNotNull, reason: 'the bill\'s other fields went on');
      expect(b.bill(id)!.blob, isNull, reason: 'the file reference waits for the file');
      expect(relay.blobs, isEmpty);

      relay.failBlobs = false;
      relay.order.clear();
      final r2 = await run(a);
      expect(r2.blobsWaiting, 0);
      expect(relay.order, ['putBlob', 'put'], reason: 'the file is stored before the op that references it');
      expect(a.pendingOps(), isEmpty);
      await run(b);
      expect(b.bill(id)!.blob, ref.hash);
      expect(await BlobStore(b, key).read(ref.hash, transport: relay), bytesOf(400, 1));
    });

    test('no snapshot while an op waits for its file (it would carry the reference early)', () async {
      final a = mk();
      bump(a);
      await run(a);
      final ref = await BlobStore(a, key).add(bytesOf(300, 9), 'jpg');
      a.importBill(nb('snap'), file: ref);
      relay.failBlobs = true;
      now = now.add(const Duration(days: 8));
      await run(a);
      expect(relay.calls['putSnapshot'], isNull);
      relay.failBlobs = false;
      await run(a);
      expect(relay.calls['putSnapshot'], 1);
      expect(relay.declared.values.single, [ref.hash]);
    });

    test('a first sync to a new relay: the file waits for the wallet, then its op goes in the same run', () async {
      final a = mk(), b = mk();
      final ref = await BlobStore(a, key).add(bytesOf(300, 2), 'pdf');
      final (id, _) = a.importBill(nb('first'), file: ref);
      final r = await run(a);
      expect((r.blobsSent, r.blobsWaiting), (1, 0));
      expect(relay.order, ['putBlob', 'put', 'putBlob', 'put'], reason: '404 before the wallet existed, then file, then op');
      expect(a.pendingOps(), isEmpty);
      await run(b);
      expect(b.bill(id)!.blob, ref.hash);
    });

    test('a run cut off after the file but before its op: the next run PUTs the file again before the op', () async {
      final a = mk();
      bump(a);
      await run(a);
      final ref = await BlobStore(a, key).add(bytesOf(300, 3), 'jpg');
      a.importBill(nb('again'), file: ref);
      relay.failNextPut = true;
      await expectLater(run(a), throwsA(isA<SyncException>()));
      expect(a.queuedBlobs(), isEmpty, reason: 'the file itself is on the relay');
      relay.order.clear();
      await run(a);
      expect(relay.order, ['putBlob', 'put'], reason: 'again (200): its stored time is fresh when the op lands');
      expect(a.pendingOps(), isEmpty);
    });

    test('an op overtaken by another device\'s file for the same bill neither waits nor holds back snapshots', () async {
      final a = mk();
      final b = WalletRepo.inMemory(now: () => DateTime.now().millisecondsSinceEpoch + 5000)..also(repos.add); // later clock
      bump(a);
      await run(a);
      final fa = await BlobStore(a, key).add(bytesOf(300, 40), 'jpg');
      final (id, _) = a.importBill(nb('race'), file: fa);
      relay.failHashes[fa.hash] = TransportFailure.unreachable; // a's file never gets through
      await run(a);
      expect(a.pendingBlobRefs(), {fa.hash});
      final fb = await BlobStore(b, key).add(bytesOf(300, 41), 'jpg');
      b.importBill(nb('race'), file: fb);
      await run(b);
      now = now.add(const Duration(days: 8));
      bump(a);
      await run(a);
      expect(a.bill(id)!.blob, fb.hash, reason: 'b\'s newer file wins');
      expect(a.pendingBlobRefs(), isEmpty, reason: 'the overtaken op references nothing now');
      expect(relay.calls['putSnapshot'], 1, reason: 'not held back by a\'s failing file');
      expect(relay.declared.values.single, [fb.hash]);
    });

    test('a file the relay is too full for (507) does not block snapshots; it and its op stay queued', () async {
      final a = mk();
      bump(a);
      await run(a);
      final big = await BlobStore(a, key).add(bytesOf(300, 42), 'pdf');
      final (id, _) = a.importBill(nb('full'), file: big);
      relay.failHashes[big.hash] = TransportFailure.full;
      now = now.add(const Duration(days: 8));
      await run(a);
      expect(relay.calls['putSnapshot'], 1, reason: 'the snapshot is what frees room');
      expect(relay.declared, isEmpty, reason: 'no set: this device\'s view names a file the relay does not have');
      expect(a.queuedBlobs(), [big.hash]);
      expect(a.pendingBlobRefs(), {big.hash}, reason: 'its file fields still wait');
      expect(a.evictBlobs(0), 0, reason: 'pinned');
      relay.failHashes.clear();
      await run(a);
      expect(a.pendingOps(), isEmpty);
      final c = mk();
      await run(c);
      expect(c.bill(id)!.blob, big.hash);
    });

    test('H -> H2: while A\'s file that did not fit waits, its snapshots declare no set, so GC keeps B\'s file H', () async {
      final b = mk();
      final h = await BlobStore(b, key).add(bytesOf(300, 60), 'jpg');
      final (id, _) = b.importBill(nb('h2'), file: h);
      await run(b);
      await snapshotBy(b, const []); // s1 declares [H]
      now = now.add(const Duration(days: 31));
      // A, with a later clock, has its own file H2 for the same bill before it ever synced.
      final a = WalletRepo.inMemory(now: () => DateTime.now().millisecondsSinceEpoch + 5000)..also(repos.add);
      final h2 = await BlobStore(a, key).add(bytesOf(300, 61), 'jpg');
      a.importBill(nb('h2'), file: h2);
      relay.failHashes[h2.hash] = TransportFailure.full;
      await run(a);
      now = now.add(const Duration(days: 8));
      bump(a);
      await run(a);
      expect(a.bill(id)!.blob, h2.hash, reason: 'A\'s view');
      expect(relay.calls['putSnapshot'], 3, reason: 'A\'s snapshots still go (they free room)');
      expect(relay.calls['putSnapshotBlobs'], 1, reason: 'only B\'s s1');
      expect(relay.declared, isEmpty, reason: 'neither kept snapshot has a set');
      expect(relay.gcRuns, 0);
      expect(relay.blobs.keys, [h.hash], reason: 'B, the relay and every file still name H');
      // H2 lands: later snapshots declare sets again and GC runs as usual.
      relay.failHashes.clear();
      await run(a);
      await run(b);
      expect(b.bill(id)!.blob, h2.hash);
      await snapshotBy(a, [b]);
      await snapshotBy(b, [a]);
      expect(relay.gcRuns, greaterThan(0));
      expect(relay.blobs.keys, [h2.hash], reason: 'H is no longer referenced and older than the grace');
    });

    test('a new (wiped) relay gets every cached file a live bill points to again', () async {
      final a = mk();
      final f1 = await BlobStore(a, key).add(bytesOf(200, 4), 'jpg'), f2 = await BlobStore(a, key).add(bytesOf(200, 5), 'jpg');
      a.importBill(nb('w1'), file: f1);
      final (gone, _) = a.importBill(nb('w2'), file: f2);
      await run(a);
      a.deleteBill(gone);
      await run(a);
      relay.wipe();
      await run(a);
      expect(relay.blobs.keys, [f1.hash], reason: 'the live bill\'s file; the deleted one is not needed');
    });

    test('LRU: never evicts a file waiting for upload, nor one a pending op references; others go', () async {
      final a = mk();
      bump(a);
      await run(a);
      final store = BlobStore(a, key, maxCacheBytes: 1 << 20);
      final up = await store.add(bytesOf(1000, 6), 'jpg');
      a.importBill(nb('lru1'), file: up);
      await run(a);
      final pinned = await store.add(bytesOf(1000, 7), 'jpg');
      await run(a); // uploaded, not yet referenced
      a.importBill(nb('lru2'), file: pinned);
      relay.failBlobs = true;
      await run(a); // the op referencing `pinned` is held; `pinned` is uploaded already
      final waiting = await store.add(bytesOf(1000, 8), 'jpg');
      expect(a.evictBlobs(0), 1, reason: 'only the uploaded, unreferenced file');
      expect(a.hasCachedBlob(up.hash), isFalse);
      expect((a.hasCachedBlob(pinned.hash), a.hasCachedBlob(waiting.hash)), (true, true));
    });
  });

  group('declared sets', () {
    test('a snapshot declares exactly the live bills\' files', () async {
      final a = mk();
      final store = BlobStore(a, key);
      final f1 = await store.add(bytesOf(200, 10), 'jpg'), f2 = await store.add(bytesOf(200, 11), 'jpg');
      a.importBill(nb('d1'), file: f1);
      a.importBill(nb('d2'), file: f1); // the same file on two bills
      final (dead, _) = a.importBill(nb('d3'), file: f2);
      a.importBill(nb('d4')); // no file
      a.deleteBill(dead);
      await run(a);
      await snapshotBy(a, const []);
      expect(relay.calls['putSnapshot'], 1);
      expect(relay.declared.values.single, [f1.hash]);
      expect(relay.blobs.keys.toSet(), {f1.hash, f2.hash}, reason: 'nothing deleted by the client');
    });

    test('an api-3 relay gets no declared set (and nothing is ever deleted)', () async {
      relay.api = 3;
      final a = mk();
      final f = await BlobStore(a, key).add(bytesOf(200, 12), 'jpg');
      final (id, _) = a.importBill(nb('old'), file: f);
      await run(a);
      a.deleteBill(id);
      await snapshotBy(a, const []);
      await snapshotBy(a, const []);
      expect(relay.calls['putSnapshot'], 2);
      expect(relay.calls['putSnapshotBlobs'], isNull);
      expect(relay.blobs.keys, [f.hash]);
      expect((await run(a)).relayCollectsBlobs, isFalse);
      relay.api = 4;
      expect((await run(a)).relayCollectsBlobs, isTrue, reason: 'the app line "Old bill files are cleaned up on the relay."');
    });
  });

  group('relay GC and two devices', () {
    // Bills have no undelete: a deleted bill comes back through a re-import (the real revive path), which brings the
    // file that import reads, sealed anew (a new hash), or none.
    test('A deletes a bill, B brings it back (re-import with the photo) before GC: its file is there after GC runs', () async {
      final a = mk(), b = mk();
      final f = await BlobStore(a, key).add(bytesOf(500, 20), 'jpg');
      final (id, _) = a.importBill(nb('undo'), file: f);
      await run(a);
      await run(b);
      a.deleteBill(id);
      await run(a);
      await run(b);
      expect(b.bill(id)!.deleted, isTrue);
      now = now.add(const Duration(days: 20));
      final again = await BlobStore(b, key).add(bytesOf(500, 20), 'jpg'); // the same photo, read again
      final (revived, _) = b.importBill(nb('undo'), file: again);
      expect(revived, id);
      relay.order.clear();
      await run(b);
      expect(relay.order.take(2), ['putBlob', 'put'], reason: 'the file before the op that brings the bill back');
      await run(a);
      expect((a.bill(id)!.deleted, a.bill(id)!.blob), (false, again.hash));
      // Later snapshots (both declared) and well past the grace: GC runs, the live file stays, the old one goes.
      await snapshotBy(a, [b]);
      await snapshotBy(b, [a]);
      now = now.add(const Duration(days: 40));
      await snapshotBy(a, [b]);
      await snapshotBy(b, [a]);
      expect(relay.gcRuns, greaterThan(0));
      expect(relay.blobs.keys, [again.hash]);
      final c = mk();
      await run(c);
      expect(await BlobStore(c, key).read(again.hash, transport: relay), bytesOf(500, 20));
    });

    test('a file no live bill points to goes after the grace; one a live bill points to never does', () async {
      final a = mk(), b = mk();
      final f = await BlobStore(a, key).add(bytesOf(500, 21), 'jpg'), keep = await BlobStore(a, key).add(bytesOf(500, 22), 'jpg');
      final (id, _) = a.importBill(nb('gc'), file: f);
      final (live, _) = a.importBill(nb('live'), file: keep);
      await run(a);
      await run(b);
      a.deleteBill(id);
      await run(a);
      await snapshotBy(a, [b]);
      await snapshotBy(b, [a]);
      expect(relay.blobs.keys.toSet(), {f.hash, keep.hash}, reason: 'within the 30 days');
      now = now.add(const Duration(days: 31));
      await snapshotBy(a, [b]);
      expect(relay.blobs.keys, [keep.hash], reason: 'undeclared by both kept snapshots and older than the grace');
      expect(a.cachedBlob(f.hash, touch: false), isNotNull, reason: 'still in the cache until evicted');
      final c = mk();
      await run(c);
      expect(c.bill(live)!.blob, keep.hash);
      expect(await BlobStore(c, key).read(keep.hash, transport: relay), bytesOf(500, 22));
    });
  });

  group('schema 14 → 15', () {
    test('the migration keeps the queued uploads and drops the old tables', () {
      final tmp = Directory.systemTemp.createTempSync('bw-p14-');
      addTearDown(() => tmp.deleteSync(recursive: true));
      final path = '${tmp.path}/w.db';
      final old = WalletRepo.open(path);
      final h1 = 'a' * 64, h2 = 'b' * 64, h3 = 'c' * 64;
      // The schema-14 local tables, as that build made them.
      old.db.execute('DROP TABLE blob_cache');
      old.db.execute(
          'CREATE TABLE blob_cache(hash TEXT PRIMARY KEY, sealed BLOB NOT NULL, used_at INTEGER NOT NULL, bytes INTEGER NOT NULL)');
      old.db.execute('CREATE TABLE blob_outbox(hash TEXT PRIMARY KEY)');
      old.db.execute('CREATE TABLE blob_delete(hash TEXT PRIMARY KEY)');
      old.db.execute('CREATE TABLE blob_own(hash TEXT PRIMARY KEY)');
      for (final (i, h) in [h1, h2].indexed) {
        old.db.execute('INSERT INTO blob_cache VALUES(?, ?, ?, ?)', [h, Uint8List(10), i + 1, 10]);
      }
      old.db.execute('INSERT INTO blob_outbox VALUES(?)', [h1]);
      old.db.execute('INSERT INTO blob_outbox VALUES(?)', [h3]); // queued but not cached: nothing to send
      old.db.execute('INSERT INTO blob_delete VALUES(?)', [h2]);
      old.db.execute('INSERT INTO blob_own VALUES(?)', [h1]);
      old.db.execute("UPDATE meta SET value = '14' WHERE key = 'schema'");
      old.setSyncCursor('dev', 3);
      old.importBill(nb('mig'), file: BlobRef(hash: h2, type: 'jpg', bytes: 10)); // a live bill with the cached h2 (setup)
      old.db.execute('DELETE FROM outbox'); // already synced
      old.close();

      final up = WalletRepo.open(path);
      addTearDown(up.close);
      expect(up.db.select("SELECT value FROM meta WHERE key = 'schema'").first['value'], '${WalletRepo.schemaVersion}');
      expect(up.queuedBlobs(), [h1]);
      expect(up.hasCachedBlob(h2), isTrue);
      final tables = {for (final r in up.db.select("SELECT name FROM sqlite_master WHERE type = 'table'")) r['name']};
      expect(tables.intersection({'blob_outbox', 'blob_delete', 'blob_own'}), isEmpty);
      expect(up.localValue(WalletRepo.blobReuploadKey), jsonEncode([h2]), reason: 'the live bills\' cached files, once more');
      expect(up.evictBlobs(0), 1, reason: 'the uploaded one only');
      expect(up.queuedBlobs(), [h1]);
      expect(up.syncCursors(), isEmpty, reason: 'a schema bump replays the relay once');
      up.close();
      final again = WalletRepo.open(path);
      addTearDown(again.close);
      expect(again.queuedBlobs(), [h1], reason: 'the migration runs once');
    });

    test('after the upgrade, the listed files go up again; one that keeps failing costs one PUT a run, no more', () async {
      final a = mk();
      final store = BlobStore(a, key);
      final f = await store.add(bytesOf(400, 50), 'jpg'), k = await store.add(bytesOf(400, 53), 'jpg');
      a.importBill(nb('lost'), file: f);
      a.importBill(nb('kept'), file: k);
      await run(a);
      relay.loseBlob(f.hash); // an api-3 build deleted them while live bills still pointed at them
      relay.loseBlob(k.hash);
      a.setLocalValue(WalletRepo.blobReuploadKey, jsonEncode([f.hash, k.hash])); // as the 14 -> 15 migration leaves it
      relay.failHashes[f.hash] = TransportFailure.unreachable;
      await run(a);
      expect(relay.blobs.keys, [k.hash]);
      expect(a.localValue(WalletRepo.blobReuploadKey), jsonEncode([f.hash]), reason: 'only the unconfirmed one stays listed');
      relay.order.clear();
      await run(a);
      expect(relay.order.where((o) => o == 'putBlob'), hasLength(1), reason: 'the failing one only, not the whole cache');
      relay.failHashes.clear();
      await run(a);
      expect(relay.blobs.keys.toSet(), {f.hash, k.hash});
      expect(a.localValue(WalletRepo.blobReuploadKey), isNull);
      relay.order.clear();
      await run(a);
      expect(relay.order, isNot(contains('putBlob')), reason: 'done');
    });

    test('a relay without blob storage ends the upgrade re-upload', () async {
      final a = mk();
      final f = await BlobStore(a, key).add(bytesOf(400, 54), 'jpg');
      a.importBill(nb('nostore'), file: f);
      await run(a);
      a.setLocalValue(WalletRepo.blobReuploadKey, jsonEncode([f.hash]));
      relay.blobRoutes = false;
      await run(a);
      expect(a.localValue(WalletRepo.blobReuploadKey), isNull);
    });
  });

  group('the real relay (api 4)', () {
    late Directory dir;
    late Relay server;
    late Uri base;
    final logs = <String>[];
    setUp(() async {
      dir = Directory.systemTemp.createTempSync('bw-p14-relay-');
      logs.clear();
      server = Relay(data: dir, log: logs.add);
      base = Uri.parse('http://127.0.0.1:${(await server.serve(port: 0)).port}');
    });
    tearDown(() async {
      await server.close();
      dir.deleteSync(recursive: true);
    });

    test('a near-full relay: a file over the limit (507) does not stop the snapshot that frees room', () async {
      final small = Directory.systemTemp.createTempSync('bw-p14-full-');
      final slogs = <String>[];
      final full = Relay(data: small, log: slogs.add, maxBytes: 16000);
      final sbase = Uri.parse('http://127.0.0.1:${(await full.serve(port: 0)).port}');
      addTearDown(() async {
        await full.close();
        small.deleteSync(recursive: true);
      });
      final t = RelayTransport(sbase, key);
      addTearDown(t.close);
      final a = mk();
      Future<SyncReport> go() => SyncEngine(t, key, now: () => now).run(a);
      for (var i = 0; i < 10; i++) {
        bump(a);
        await go();
      }
      final big = await BlobStore(a, key).add(bytesOf(20000, 52), 'pdf'); // never fits
      a.importBill(nb('huge'), file: big);
      final before = (await t.state()).bytes!;
      now = now.add(const Duration(days: 8));
      final r = await go();
      expect(slogs.where((l) => l.startsWith('relay put-blob 507')), isNotEmpty);
      expect(slogs.where((l) => l.startsWith('relay put-snap 201')), hasLength(1));
      expect(slogs.where((l) => l.startsWith('relay put-set')), isEmpty, reason: 'no set while that file waits');
      expect(r.blobsWaiting, 1);
      expect(a.pendingBlobRefs(), {big.hash}, reason: 'its op waits, pinned');
      expect((await t.state()).bytes!, lessThan(before), reason: 'the snapshot let the relay prune the sync files');
    });

    test('deleting a bill, a re-import and a restore send no DELETE', () async {
      final a = mk(), b = mk();
      final t = RelayTransport(base, key);
      addTearDown(t.close);
      final f = await BlobStore(a, key).add(bytesOf(600, 30), 'jpg');
      final (id, _) = a.importBill(nb('real'), file: f);
      await SyncEngine(t, key).run(a);
      a.deleteBill(id);
      await SyncEngine(t, key).run(a);
      a.importBill(nb('real'));
      await SyncEngine(t, key).run(a);
      await restoreBackupBytes(b, await backupBytes(a, key), key);
      await SyncEngine(t, key).run(b);
      await SyncEngine(t, key).run(a);
      expect(logs.where((l) => l.contains('delete-blob')), isEmpty);
      expect(logs.where((l) => l.contains('put-blob 20')), isNotEmpty);
      expect(await t.getBlob(f.hash), isNotNull);
    });
  });
}

extension<T> on T {
  T also(void Function(T) f) {
    f(this);
    return this;
  }
}
